## ----weighted-summary---------------------------------------------------------
weighted.mesh <- mesh.surface.graph(5, 5, surface = "saddle", amplitude = 0.8)

coords.combinatorial <- grip.layout(
  weighted.mesh$edges,
  n = weighted.mesh$n,
  dim = 3,
  preset = "mesh",
  seed = 1
)

coords.weighted <- grip.layout.weighted(
  weighted.mesh$edges,
  n = weighted.mesh$n,
  edge_weights = weighted.mesh$edge_weights,
  dim = 3,
  preset = "mesh",
  seed = 1
)

coords.weighted.lgkk <- grip.layout.weighted(
  weighted.mesh$edges,
  n = weighted.mesh$n,
  edge_weights = weighted.mesh$edge_weights,
  dim = 3,
  preset = "mesh",
  lgkk_polish_rounds = 6L,
  seed = 1
)

gkk.prepared <- grip.prepare.geodesic.kk(
  weighted.mesh$edges,
  n = weighted.mesh$n,
  edge_weights = weighted.mesh$edge_weights
)

weighted.summary <- do.call(
  rbind,
  list(
    cbind(
      method = "Combinatorial GRIP",
      grip.score.geodesic.kk(
        coords.combinatorial,
        prepared = gkk.prepared
      )[, c(
        "gkk.weighted.rel.rmse",
        "gkk.weighted.rmse",
        "gkk.mean.rel.path.error"
      )]
    ),
    cbind(
      method = "Weighted GRIP",
      grip.score.geodesic.kk(
        coords.weighted,
        prepared = gkk.prepared
      )[, c(
        "gkk.weighted.rel.rmse",
        "gkk.weighted.rmse",
        "gkk.mean.rel.path.error"
      )]
    ),
    cbind(
      method = "Weighted GRIP + LGKK polish",
      grip.score.geodesic.kk(
        coords.weighted.lgkk,
        prepared = gkk.prepared
      )[, c(
        "gkk.weighted.rel.rmse",
        "gkk.weighted.rmse",
        "gkk.mean.rel.path.error"
      )]
    )
  )
)

paper_kable(
  weighted.summary,
  caption = paper_table_caption(
    "Weighted saddle-surface example scored with geodesic-KK criteria.",
    "GKK Rel = weighted relative RMSE; GKK RMSE = weighted RMSE; Path Rel = mean relative path error."
  ),
  digits = 3
)


## ----weighted-figure, fig.cap="Weighted mesh example. Top left: target saddle geometry. Top right: combinatorial GRIP. Bottom left: weighted GRIP. Bottom right: weighted GRIP followed by LGKK polish.", fig.alt="A four-panel comparison of a saddle-surface mesh showing the target geometry, the combinatorial layout, the weighted layout, and the weighted layout with LGKK polish.", fig.width=11.2, fig.height=8----
